describe('Cart Badge and Add/Remove Product Functionality', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();
    cy.get('[data-test="inventory-container"]').should('be.visible');
  });

  it('should add product to cart and display badge with correct count', () => {
    cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').should('be.visible').click();

    cy.get('.shopping_cart_badge').should('be.visible').and('have.text', '1');

    cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').should('not.exist');
    cy.get('[data-test="remove-sauce-labs-backpack"]').should('be.visible').and('contain.text', 'Remove');
  });

  it('should remove product from cart and remove badge from page', () => {
    cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').click();

    cy.get('.shopping_cart_badge').should('have.text', '1');

    cy.get('[data-test="remove-sauce-labs-backpack"]').click();

    cy.get('.shopping_cart_badge').should('not.exist');

    cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').should('be.visible').and('contain.text', 'Add to cart');
  });

  it('should handle multiple add and remove operations maintaining accurate badge count', () => {
    cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('.shopping_cart_badge').should('have.text', '1');

    cy.get('[data-test="add-to-cart-sauce-labs-bike-light"]').click();
    cy.get('.shopping_cart_badge').should('have.text', '2');

    cy.get('[data-test="remove-sauce-labs-backpack"]').click();
    cy.get('.shopping_cart_badge').should('have.text', '1');

    cy.get('[data-test="remove-sauce-labs-bike-light"]').click();
    cy.get('.shopping_cart_badge').should('not.exist');
  });
});
